diff --git a/src/Api/ExportsController.cs b/src/Api/ExportsController.cs
index 9f8e7d6..0a1b2c3 100644
--- a/src/Api/ExportsController.cs
+++ b/src/Api/ExportsController.cs
@@ -22,6 +22,21 @@ public class ExportsController : ControllerBase
         return Ok(result);
     }

+    [HttpPost("exports/orders")]
+    public async Task<ActionResult<ExportJob>> ExportOrders([FromBody] ExportOrdersRequest request, CancellationToken ct)
+    {
+        if (request.DateRange.Start > request.DateRange.End)
+            return BadRequest("Start date must be before end date.");
+        if (request.DateRange.End > DateTime.UtcNow)
+            return BadRequest("End date cannot be in the future.");
+
+        var job = await _exportService.StartOrderExportAsync(request, ct);
+        return Accepted($"/exports/orders/{job.Id}", job);
+    }
 }
