@@ -40,6 +40,17 @@ public sealed class OrdersRepository
     }

+    public async Task<IReadOnlyList<Order>> FindInRangeAsync(DateTime start, DateTime end, CancellationToken ct)
+    {
+        return await _db.Orders
+            .Where(o => o.CreatedAt >= start && o.CreatedAt < end)
+            .AsNoTracking()
+            .ToListAsync(ct);
+    }
+}
