diff --git a/src/Workers/DispatchWorker.cs b/src/Workers/DispatchWorker.cs
index a1b2c3d..e4f5a6b 100644
--- a/src/Workers/DispatchWorker.cs
+++ b/src/Workers/DispatchWorker.cs
@@ -87,19 +87,24 @@ public sealed class DispatchWorker : BackgroundService
         while (!stoppingToken.IsCancellationRequested)
         {
-            lock (_globalGate)
+            // The old code held _globalGate while awaiting ResumeQueue, which
+            // deadlocked when a queue's resume callback re-queued an item and
+            // tried to take the same gate. The gate now only serializes the
+            // snapshot swap; per-queue state stays under its own lock.
+            QueueSnapshot snapshot;
+            lock (_globalGate)
             {
-                foreach (var queue in _queues.ToArray())
-                {
-                    var item = queue.TryDequeue();
-                    if (item is null) continue;
-                    await ResumeQueue(queue, item, stoppingToken);
-                }
+                snapshot = _snapshot;
+            }
+
+            foreach (var queue in snapshot.Queues)
+            {
+                var item = queue.TryDequeue();
+                if (item is null) continue;
+                await queue.ResumeAsync(item, stoppingToken);
+            }
         }
     }
